@Component
class AnalitykaListener {
    private final AtomicInteger licznikZamowien = new AtomicInteger();

    @EventListener
    public void naZamowienie(ZamowienieUtworzone z) {
        licznikZamowien.incrementAndGet(); // natychmiast, synchronicznie
    }
}

@Component
class RaportScheduler {
    private final AnalitykaListener analityka;
    private volatile List<String> ostatniRaport = List.of();

    @Scheduled(fixedDelay = 100)
    public void generujRaport() {
        if (analityka.getLicznikZamowien() > 0) {
            ostatniRaport = List.of("RAPORT: " + analityka.getLicznikZamowien() + " zamowien");
        }
    }

    public List<String> getOstatniRaport() {
        return ostatniRaport;
    }
}

